import{describe,it,expect}from"vitest";import{TAJ_BUILD_STAGES,TAJ_MATERIALS_ORIGINS,HISTORICAL_MYTHS_FLAGGED,getActiveStageIndex,filterMaterials,getTajConstructionStats}from"../../frontend/taj-mahal-scrollytelling/script.js";describe("Taj Mahal Construction Stages Dataset Integrity",()=>{it("contains 6 chronological construction build-up stages",()=>{expect(TAJ_BUILD_STAGES.length).toBe(6)}),it("verifies progress percentages ascend from foundation to completion (16% to 100%)",()=>{expect(TAJ_BUILD_STAGES[0].progressPercentage).toBe(16),expect(TAJ_BUILD_STAGES[TAJ_BUILD_STAGES.length-1].progressPercentage).toBe(100);for(let e=0;e<TAJ_BUILD_STAGES.length-1;e++)expect(TAJ_BUILD_STAGES[e].progressPercentage).toBeLessThan(TAJ_BUILD_STAGES[e+1].progressPercentage)}),it("every build stage contains required architectural properties",()=>{TAJ_BUILD_STAGES.forEach((e,t)=>{expect(e,`Stage ${t} missing id`).toHaveProperty("id"),expect(e,`Stage ${t} missing stepNumber`).toHaveProperty("stepNumber"),expect(e,`Stage ${t} missing title`).toHaveProperty("title"),expect(e,`Stage ${t} missing theme`).toHaveProperty("theme"),expect(e,`Stage ${t} missing summary`).toHaveProperty("summary"),expect(e,`Stage ${t} missing details`).toHaveProperty("details"),expect(e,`Stage ${t} missing materials`).toHaveProperty("materials"),expect(Array.isArray(e.materials)).toBe(!0),expect(e.materials.length).toBeGreaterThan(0)})})}),describe("Material Sourcing Dataset & Search Filter",()=>{it("contains at least 6 verified material origins across Asia",()=>{expect(TAJ_MATERIALS_ORIGINS.length).toBeGreaterThanOrEqual(6)}),it("filters materials accurately by search query",()=>{const e=filterMaterials(TAJ_MATERIALS_ORIGINS,"marble");expect(e.length).toBe(1),expect(e[0].stone).toContain("White Marble");const t=filterMaterials(TAJ_MATERIALS_ORIGINS,"Tibet");expect(t.length).toBe(1),expect(t[0].stone).toBe("Turquoise")}),it("returns all materials when search query is empty",()=>{expect(filterMaterials(TAJ_MATERIALS_ORIGINS,"").length).toBe(TAJ_MATERIALS_ORIGINS.length)})}),describe("Flagged Historical Myths",()=>{it("contains flagged disputed claims with clear warning verdicts",()=>{expect(HISTORICAL_MYTHS_FLAGGED.length).toBeGreaterThanOrEqual(3),HISTORICAL_MYTHS_FLAGGED.forEach(e=>{expect(e).toHaveProperty("claim"),expect(e).toHaveProperty("verdict"),expect(e).toHaveProperty("explanation"),expect(e.verdict).toContain("DISPUTED")})})}),describe("Scroll Stage Index Calculation & Stats",()=>{it("calculates active stage index based on scroll percentage",()=>{expect(getActiveStageIndex(0,6)).toBe(0),expect(getActiveStageIndex(30,6)).toBe(1),expect(getActiveStageIndex(50,6)).toBe(3),expect(getActiveStageIndex(99,6)).toBe(5)}),it("computes construction statistics correctly",()=>{const e=getTajConstructionStats();expect(e.workforceEstimate).toContain("20,000"),expect(e.chiefArchitect).toBe("Ustad Ahmad Lahori"),expect(e.buildStagesCount).toBe(6)})});